import{_ as r}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as e,o,af as n}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const m=JSON.parse('{"title":"Security Agents","description":"","frontmatter":{},"headers":[],"relativePath":"zh/products/ai-coding/cursor/security-agents.md","filePath":"zh/products/ai-coding/cursor/security-agents.md","lastUpdated":1787110548000}'),a={name:"zh/products/ai-coding/cursor/security-agents.md"};function s(i,t,l,d,g,u){return o(),e("div",null,[...t[0]||(t[0]=[n('<h1 id="security-agents" tabindex="-1">Security Agents <a class="header-anchor" href="#security-agents" aria-label="Permalink to &quot;Security Agents&quot;">​</a></h1><p>Security Agents 扫描代码里的 <strong>安全 bug、危险模式和漏洞</strong>。它们是 <a href="https://cursor.com/automations/from-cursor/security" target="_blank" rel="noreferrer">Automations</a> 上的 Cursor 托管 Agent，并且<strong>需要 Cloud Agents</strong>。</p><blockquote><p>官方：<a href="https://cursor.com/docs/security-agents" target="_blank" rel="noreferrer">Security Agents</a>。</p><p>两种类型：<strong>Security Reviewer</strong>（PR / MR）和 <strong>Vulnerability Scanner</strong>（cron）。本地技能：<code>/review-security</code>。计费进<strong>团队用量池</strong>，不是你的个人配额。</p></blockquote><h2 id="先决条件" tabindex="-1">先决条件 <a class="header-anchor" href="#先决条件" aria-label="Permalink to &quot;先决条件&quot;">​</a></h2><ul><li>账号能用 Cloud Agents（付费计划；管理员已接源代码托管）</li><li>打得开 <a href="https://cursor.com/automations/from-cursor/security" target="_blank" rel="noreferrer">Automations</a></li><li>要在编辑器或 <a href="https://cursor.com/agents" target="_blank" rel="noreferrer">cursor.com/agents</a> 用 <code>/review-security</code> / <code>/review</code>，需要 Cursor <strong>3.7+</strong></li><li>若 <a href="./pr-routing.html">PR Routing</a> 要读 Security Review Context，需要 <strong>Team 或 Enterprise</strong></li></ul><h2 id="学习目标" tabindex="-1">学习目标 <a class="header-anchor" href="#学习目标" aria-label="Permalink to &quot;学习目标&quot;">​</a></h2><p>读完本页你能：</p><ol><li>分清 Security Reviewer、Vulnerability Scanner，以及它们和 Bugbot 的差别</li><li>配触发器、至少一个 tool / MCP、自定义指令</li><li>推送前在当前分支跑 <code>/review-security</code></li><li>知道用量记在<strong>团队池</strong>，不记在你头上</li></ol><hr><h2 id="两种-agent" tabindex="-1">两种 Agent <a class="header-anchor" href="#两种-agent" aria-label="Permalink to &quot;两种 Agent&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类型</th><th>触发</th><th>干什么</th></tr></thead><tbody><tr><td><strong>Security Reviewer</strong></td><td>Automations 的 Git 触发：pull request / merge request</td><td>在<strong>代码审查时</strong>拦漏洞</td></tr><tr><td><strong>Vulnerability Scanner</strong></td><td>Cron</td><td>扫<strong>静止</strong>代码库——存量问题、漏网的旧洞、PR 审查没看到的</td></tr></tbody></table><p>两者都跑在 Automations 平台，都需要 Cloud Agents。可以用 Cursor 云，不必另搭 VM。</p><p>这<strong>不是</strong> Bugbot。Bugbot 审 PR diff（bug / 安全 / 质量）并留言。Security Agents 是另一组 Cursor 托管 Automation。PR Routing 可以<strong>读</strong>两边：<a href="./pr-routing.html">Bugbot Review Context</a> 和 Security Review Context。</p><h2 id="配置" tabindex="-1">配置 <a class="header-anchor" href="#配置" aria-label="Permalink to &quot;配置&quot;">​</a></h2><p>打开 <a href="https://cursor.com/automations/from-cursor/security" target="_blank" rel="noreferrer">Automations 里的 Security Agents</a>。</p><ol><li>选 <strong>Security Reviewer</strong> 或 <strong>Vulnerability Scanner</strong></li><li>设 <strong>triggers</strong>（PR / MR 事件 vs cron）</li><li>打开或关掉内置 <strong>security checks</strong></li><li>写 <strong>custom instructions</strong>：优先看什么、项目安全预期、Agent 该怎么表现</li><li>接 <strong>tools 和 MCPs</strong> — 每个 Agent <strong>至少要有一个</strong> 才能跑</li><li>保存。运行记录在 Automations 历史里</li></ol><p>用 tools / MCP 把 finding 送到 Slack 或 issue tracker，说明何时调用哪个 MCP，并在报告前补上下文。</p><h2 id="在你的-agent-里跑" tabindex="-1">在你的 Agent 里跑 <a class="header-anchor" href="#在你的-agent-里跑" aria-label="Permalink to &quot;在你的 Agent 里跑&quot;">​</a></h2><p>推送前用 <code>/review-security</code> 或 <code>/review</code>。</p><table tabindex="0"><thead><tr><th>旋钮</th><th>官方默认</th></tr></thead><tbody><tr><td><strong>审哪段 diff</strong></td><td>当前<strong>分支</strong>相对 base：已提交 <strong>和</strong> 未提交的改动</td></tr><tr><td><strong>对比哪条 base</strong></td><td>默认 base 分支。若不是 <code>main</code>，告诉 Agent 要比哪条，或让它从上下文推断</td></tr></tbody></table><p>想收窄时，明确说<strong>只审未提交</strong>改动。</p><p><code>/review</code> 和 <code>/review-security</code> 在 <strong>Cursor 3.7+</strong> 以及 <a href="https://cursor.com/agents" target="_blank" rel="noreferrer">cursor.com/agents</a> 可用。<strong>CLI 支持即将到来</strong> — 不要写成现在就能 <code>agent /review-security</code>。</p><h2 id="计费" tabindex="-1">计费 <a class="header-anchor" href="#计费" aria-label="Permalink to &quot;计费&quot;">​</a></h2><p>Security Agents 按<strong>团队用量</strong>计费：</p><ul><li>记入团队 <strong>usage pool</strong></li><li>跑在<strong>共享团队服务账号</strong>下</li><li><strong>不影响</strong>任何个人用户的用量</li></ul><p>Automations 会创建 Cloud Agents；底层模型费率见 <a href="https://cursor.com/docs/models-and-pricing.md#model-pricing" target="_blank" rel="noreferrer">Cloud agent pricing</a>。</p><h2 id="分析与运行记录" tabindex="-1">分析与运行记录 <a class="header-anchor" href="#分析与运行记录" aria-label="Permalink to &quot;分析与运行记录&quot;">​</a></h2><p>三次运行汇总的三个指标：</p><table tabindex="0"><thead><tr><th>指标</th><th>含义</th></tr></thead><tbody><tr><td><strong>Vulnerabilities found</strong></td><td>报告的安全 finding</td></tr><tr><td><strong>Issues fixed</strong></td><td>之后被修掉的 finding</td></tr><tr><td><strong>Resolution rate</strong></td><td>已修复占已报告的比例</td></tr></tbody></table><p>Cursor 用 <strong>LLM 看增量 diff</strong> 判断被标出的问题是否真的修了。</p><p>每次运行都记在 Automations：何时跑、用了哪些工具、最终状态、耗时。打开一次运行可看底下的 Cloud Agent。</p><h2 id="什么时候用" tabindex="-1">什么时候用 <a class="header-anchor" href="#什么时候用" aria-label="Permalink to &quot;什么时候用&quot;">​</a></h2><ul><li>PR 门禁：Security Reviewer 挂在 pull / merge request 事件</li><li>定期基线：Vulnerability Scanner 走 cron，不依赖 PR 流量</li><li>本地推送前：对当前分支 <code>/review-security</code></li><li>喂给 PR Routing：打开 <strong>Security Review Context</strong>，低风险自动批准要等这些 finding</li></ul><p>只要通用 bug / 质量审查时，继续只用 Bugbot。</p><h2 id="常见陷阱" tabindex="-1">常见陷阱 <a class="header-anchor" href="#常见陷阱" aria-label="Permalink to &quot;常见陷阱&quot;">​</a></h2><table tabindex="0"><thead><tr><th>陷阱</th><th>正确做法</th></tr></thead><tbody><tr><td>当成换了名字的 Bugbot</td><td>不同产品。Bugbot 给 diff 留言；这是托管 Security Agent</td></tr><tr><td>忘了 tool / MCP</td><td>官方：每个 Agent <strong>至少要有一个</strong> 才能跑</td></tr><tr><td>指望今天就能在 CLI 用</td><td>官方：<strong>CLI support is coming soon</strong></td></tr><tr><td>以为扣你的个人配额</td><td>团队用量池 + 共享服务账号</td></tr><tr><td><code>/review-security</code> 却只想看「最后一个 commit」又不说</td><td>默认是<strong>整条分支</strong>，含未提交</td></tr><tr><td>没开 Cloud Agents / 没接源代码托管</td><td>这些 Agent <strong>必须</strong>有 Cloud Agents</td></tr></tbody></table><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="./cloud-agents.html">Cloud Agents</a> — 运行时</li><li><a href="./pr-routing.html">PR Routing</a> — 可读 Security Review Context</li><li><a href="./cursor-cookbook.html#用-bugbot-审-pr">Cookbook · Bugbot</a> — 通用 PR 审查</li><li>官方：<a href="https://cursor.com/docs/security-agents" target="_blank" rel="noreferrer">Security Agents</a>、<a href="https://cursor.com/docs/cloud-agent/automations" target="_blank" rel="noreferrer">Automations</a></li></ul>',38)])])}const f=r(a,[["render",s]]);export{m as __pageData,f as default};
